import{_ as a,o,c as t,a0 as s}from"./chunks/framework.B1kV0CGF.js";const h=JSON.parse('{"title":"Molecule Laws — this.gui","description":"","frontmatter":{"layout":"readme","title":"Molecule Laws — this.gui"},"headers":[],"relativePath":"Molecule-Laws.md","filePath":"Molecule-Laws.md"}'),i={name:"Molecule-Laws.md"};function n(r,e,l,c,d,u){return o(),t("div",null,[...e[0]||(e[0]=[s(`<p><a href="https://neurons-me.github.io/GUI/docs/" target="_blank" rel="noreferrer">← Back to GUI Docs</a></p><hr><h1 id="molecule-laws" tabindex="-1">Molecule Laws <a class="header-anchor" href="#molecule-laws" aria-label="Permalink to &quot;Molecule Laws&quot;">​</a></h1><p>This document defines the architectural meaning of a molecule in this.GUI.</p><h2 id="definition" tabindex="-1">Definition <a class="header-anchor" href="#definition" aria-label="Permalink to &quot;Definition&quot;">​</a></h2><p>A molecule is a declarative law registered in <code>GuiRegistry</code>: it receives a small semantic spec, applies an explicit policy, and deterministically produces or renders a tree of GuiNodes.</p><p>A molecule learns when the system gains better registered laws, policies, constraints, and tests. It must not improvise silently at runtime.</p><h2 id="kinds" tabindex="-1">Kinds <a class="header-anchor" href="#kinds" aria-label="Permalink to &quot;Kinds&quot;">​</a></h2><p><code>resolver</code> : A pure law. It receives data and policy, then returns GuiNodes. It has no I/O, subscriptions, timers, or browser state.</p><p><code>shell</code> : A stateful boundary around one or more resolvers. It may fetch, subscribe, handle loading/error states, or read runtime context. The shape law inside the shell should still be pure and testable.</p><p><code>component</code> : A React component used directly when the behavior is primarily interactive or physical. Components can still expose semantic props, but they are not the preferred place for shape-learning rules.</p><h2 id="registry" tabindex="-1">Registry <a class="header-anchor" href="#registry" aria-label="Permalink to &quot;Registry&quot;">​</a></h2><p>For now all laws live in <code>GuiRegistry</code>. Molecules should use:</p><ul><li><code>kind: &quot;molecule&quot;</code></li><li><code>group: &quot;Molecules/&lt;Domain&gt;&quot;</code></li><li><code>moleculeKind: &quot;resolver&quot; | &quot;shell&quot; | &quot;component&quot;</code></li></ul><p>This keeps atoms, layouts, and molecules discoverable through one registry without hiding the kind of law being registered.</p><h2 id="markdowndocument" tabindex="-1">MarkdownDocument <a class="header-anchor" href="#markdowndocument" aria-label="Permalink to &quot;MarkdownDocument&quot;">​</a></h2><p><code>MarkdownDocument</code> is the first document molecule following this split:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MarkdownDocument shell</span></span>
<span class="line"><span>  fetch/loading/error</span></span>
<span class="line"><span>  -&gt; markdownToGuiNodes(source, policy)</span></span>
<span class="line"><span>  -&gt; GuiNode tree</span></span>
<span class="line"><span>  -&gt; GUI renderer</span></span></code></pre></div><p>The public contract is GUI-owned. It must not expose parser or renderer implementation details such as <code>@uiw</code>, <code>remark</code>, or <code>unified</code>.</p><hr><p><a href="https://neurons-me.github.io/GUI/docs/" target="_blank" rel="noreferrer">← Back to GUI Docs</a></p>`,21)])])}const m=a(i,[["render",n]]);export{h as __pageData,m as default};
